import{_ as d,o as a,c as e,ag as o}from"./chunks/framework.C9sp7nFj.js";const g=JSON.parse('{"title":"MovJHand 关节左右手运动","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovJHand.md","filePath":"3. 指令/1. 运动指令/MovJHand.md","lastUpdated":1778862643000}'),n={name:"3. 指令/1. 运动指令/MovJHand.md"};function r(s,t,i,h,l,c){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="movjhand-关节左右手运动" tabindex="-1">MovJHand 关节左右手运动 <a class="header-anchor" href="#movjhand-关节左右手运动" aria-label="Permalink to &quot;MovJHand 关节左右手运动&quot;">​</a></h1><p>关节左右手运动指令。该运动指令用于以指定的左右手系进行关节运动（point to point）到终点位置，<strong>仅适用于 SCARA 机型</strong>。</p><h2 id="与-hand-指令的区别" tabindex="-1">与 Hand 指令的区别 <a class="header-anchor" href="#与-hand-指令的区别" aria-label="Permalink to &quot;与 Hand 指令的区别&quot;">​</a></h2><ul><li><strong>Hand 指令</strong>：属于<strong>设置指令</strong>。运行后，后续所有运动指令（如 <code>MovJ</code>）均以其设置的手系运动。</li><li><strong>MovJHand 指令</strong>：属于<strong>运动指令</strong>。仅在该条指令执行时以指定的手系进行 PTP 运动。</li><li><strong>优先级</strong>：若 <code>Hand(Lefty)</code> 指令后紧跟 <code>MovJHand(P1, Righty)</code>，则该条 <code>MovJHand</code> 将以<strong>右手系</strong>运动。</li></ul><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovJHand(P, Scope, [V], [B], [C], [Tool], [Coord], [PayLoad], [DO])</p><p>MovJHand(目标点, 作用域, [速度], [平滑], [姿态], [工具], [坐标系], [负载], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>P</td><td>APOS 或 CPOS 变量</td><td>坐标系下的目标点位置。</td><td>必填</td></tr><tr><td>Scope</td><td>enum（Lefty / Righty / Change）</td><td>设置机器人的左右手类型：<br><code>Lefty</code>：左手设置。<br><code>Righty</code>：右手设置。<br><code>Change</code>：与点位 <code>mode</code> 手系相反。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>用于指定机器人执行时的速度。包括末端平移、旋转及外部轴速度。SPEED 变量中的 <code>per</code> 分量有效；有外部轴时，<code>exj_l</code>、<code>exj_r</code> 分量有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / RELATIVE / ABSOLUTE / DEFAULT）</td><td>机器人逼近终点时的过渡方式（无过渡、相对、绝对或缺省）。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡值。</td><td>可选，默认 C100</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>执行该轨迹时使用的工件负载参数。</td><td>可选，默认使用当前系统中设置的负载参数</td></tr><tr><td>[DO]</td><td>string</td><td>指令执行完后触发的 IO 操作（如 <code>SetDO</code>、<code>PulseOut</code> 等）。</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJHand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Lefty&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>机器人以左手系运动到 P1 点。</p>',16)])])}const u=d(n,[["render",r]]);export{g as __pageData,u as default};
